const Module = require("module");
const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) capability escape -- Node's own `Module`
// constructor (an authoritative loader capability) is passed as an
// ARGUMENT to a local, ordinary-looking `configure(...)` function. Every
// NAMED, precise loader/execution/mutation reason this analyzer models
// (Module._load, Module.registerHooks, Module.wrapper, ...) is checked
// against the CALLEE of a call/`new` expression or the TARGET of an
// assignment -- but `configure`'s callee is just an ordinary local
// function, and `Module` here is merely one of its ARGUMENTS, so no
// earlier fix (VT-307c-fix-5 through fix-11) ever saw this shape at all.
// The final VT-307d architecture review found this the more fundamental
// gap: an authoritative capability escaping into an unanalyzed function's
// parameter defeats every precise, named classification simultaneously,
// with NO unknown Node API name involved anywhere -- `configure` could,
// in principle, do exactly what `Module._load(vulnName, module, false)`
// does with the capability it was handed, and this analyzer has no way to
// prove it doesn't. VT-307c-capability-floor closes this by treating the
// ESCAPE ITSELF -- the capability leaving this classifier's provenance
// tracking, regardless of what the receiving function does with it -- as
// closure-widening. Before that fix this construct was invisible
// entirely (not even an unsupported_construct edge). It runs the moment
// this module is loaded, never inside any function, and the analyzer can
// never rule out that `configure` uses the escaped capability to load a
// different installed module, including the separate, never-imported
// top-level vt2-vuln-lib@1.9.0 instance.
function configure(loaderCapability) {
  return loaderCapability;
}
configure(Module);

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
